// ---------------------------------------------------------------------------
// WF4 · Construir el aviso técnico (para Telegram y para el email).
// Entrada ($json): los 5 datos que envía el flujo que ha fallado:
//   flujo, nodo, mensaje_error, oportunidad_id, ejecucion_id.
// Salida: { telegram, asunto, html }.
// Determinista: ningún LLM interviene.
// RGPD: este aviso NUNCA lleva datos personales del cliente (nombre, teléfono,
// email): solo datos técnicos. Telegram es un servicio externo.
// ---------------------------------------------------------------------------

// ---- 1. Escapar texto antes de meterlo en HTML ------------------------------
// Telegram (en modo HTML) y el email interpretan <, > y &. Un mensaje de error
// que los contenga rompería el aviso (pasó en WF2 el 06/10 con Markdown).
// esc() los cambia por su forma inofensiva. String() convierte números a texto.
function esc(valor) {
  return String(valor)
    .replace(/&/g, '&amp;')    // el & primero, para no estropear los siguientes
    .replace(/</g, '&lt;')     // < deja de abrir etiquetas
    .replace(/>/g, '&gt;')     // > deja de cerrarlas
    .replace(/"/g, '&quot;')   // comillas dobles (dentro de atributos)
    .replace(/'/g, '&#39;');   // comillas simples
}

// ---- 2. Limpiar cada dato: si falta o está vacío, un guion ------------------
// El flujo que llama puede no tener algún dato (p. ej. sin oportunidad).
function texto(valor) {
  // null o undefined = el dato no ha llegado.
  if (valor === null || valor === undefined) return '—';
  // trim() quita espacios y saltos de línea al principio y al final.
  const limpio = String(valor).trim();
  // Si después de limpiar no queda nada, también un guion.
  return limpio === '' ? '—' : limpio;
}

// Los cinco datos de entrada, ya limpios.
const flujo = texto($json.flujo);
const nodo = texto($json.nodo);
const oportunidad = texto($json.oportunidad_id);
const ejecucion = texto($json.ejecucion_id);
let mensaje = texto($json.mensaje_error);   // "let": puede cambiar (abajo se recorta)

// ---- 3. Recortar errores muy largos ------------------------------------------
// Un aviso tiene que leerse de un vistazo, y no se manda a un servicio externo
// más texto del necesario. 500 caracteres bastan para identificar el error;
// el detalle completo está en la ejecución de n8n (Executions).
const MAXIMO = 500;
if (mensaje.length > MAXIMO) {
  mensaje = mensaje.slice(0, MAXIMO) + '… (recortado)';
}

// ---- 4. Fecha y hora del aviso, en hora de Madrid ----------------------------
// new Date() = ahora. toLocaleString la escribe en formato español.
const cuando = new Date().toLocaleString('es-ES', {
  timeZone: 'Europe/Madrid',
  day: '2-digit', month: '2-digit', year: 'numeric',
  hour: '2-digit', minute: '2-digit', second: '2-digit',
});

// ---- 5. Mensaje de Telegram (modo HTML) -------------------------------------
// <b>...</b> = negrita. "\n" = salto de línea. TODO dato variable pasa por esc().
const telegram =
  `⚠️ <b>ERROR TÉCNICO · Reformas Amedida</b>\n\n` +
  `<b>Flujo:</b> ${esc(flujo)}\n` +
  `<b>Paso:</b> ${esc(nodo)}\n` +
  `<b>Oportunidad:</b> ${esc(oportunidad)}\n` +
  `<b>Ejecución:</b> ${esc(ejecucion)}\n` +
  `<b>Cuándo:</b> ${esc(cuando)}\n\n` +
  `<b>Error:</b>\n${esc(mensaje)}\n\n` +
  `Revisar en n8n → Executions.`;

// ---- 6. Asunto del email ------------------------------------------------------
// Sin datos del cliente (los asuntos se ven en las notificaciones del móvil).
// Si hay oportunidad, se añade su número; si no, solo el flujo.
const asunto = oportunidad === '—'
  ? `[Técnico] Error en ${flujo}`
  : `[Técnico] Error en ${flujo} · Oportunidad ${oportunidad}`;

// ---- 7. Cuerpo del email (HTML sencillo) --------------------------------------
// Una fila "etiqueta | valor". El valor SIEMPRE pasa por esc().
function fila(etiqueta, valor) {
  return `<tr><td style="padding:4px 12px 4px 0;color:#5B6B79;vertical-align:top;">${etiqueta}</td>` +
         `<td style="padding:4px 0;font-weight:bold;">${esc(valor)}</td></tr>`;
}

// Saltos de línea del error -> <br> para que se vean en el email.
const mensajeHtml = esc(mensaje).replace(/\r?\n/g, '<br>');

const html =
  `<div style="font-family:Arial,Helvetica,sans-serif;color:#1F2933;">` +
  `<div style="background:#8A1C1C;color:#FFFFFF;padding:12px 16px;border-radius:6px 6px 0 0;font-weight:bold;">` +
  `Error técnico · Reformas Amedida</div>` +
  `<div style="border:1px solid #E5E9ED;border-top:none;padding:12px 16px;border-radius:0 0 6px 6px;">` +
  `<table>` +
  fila('Flujo', flujo) + fila('Paso', nodo) + fila('Oportunidad', oportunidad) +
  fila('Ejecución', ejecucion) + fila('Cuándo', cuando) +
  `</table>` +
  `<p style="margin:12px 0 4px;color:#5B6B79;">Error:</p>` +
  `<div style="background:#F6F8FA;padding:8px 12px;border-radius:4px;font-family:monospace;">${mensajeHtml}</div>` +
  `<p style="font-size:12px;color:#5B6B79;margin-top:12px;">Aviso automático para el responsable técnico. ` +
  `No contiene datos personales del cliente. Detalle completo en n8n → Executions.</p>` +
  `</div></div>`;

// ---- 8. Salida: los tres textos listos para enviar ---------------------------
return { json: { telegram, asunto, html } };
